export default function MenuCard({
  item,
  quantity,
  addToCart,
  removeFromCart
}) {
  const outOfStock = item.stock <= 0;

  return (
    <div className="menu-card">
      {/* Badges */}
      <div className="menu-badges">
        {item.popular && <span className="badge popular">🔥 Popular</span>}
        {item.topRated && <span className="badge rated">⭐ Top Rated</span>}
      </div>

      <h4>{item.name}</h4>
      <p>₹{item.price}</p>

      <p className={`stock ${outOfStock ? "out" : ""}`}>
        {outOfStock ? "Out of Stock" : `Stock: ${item.stock}`}
      </p>

      {/* ADD / Quantity Controls */}
      {!outOfStock && (
        <>
          {quantity === 0 ? (
            <button
              className="add-btn"
              onClick={() => addToCart(item)}
            >
              Add to Cart
            </button>
          ) : (
            <div className="qty-controls">
              <button
                className="qty-btn"
                onClick={() => removeFromCart(item.id)}
              >
                −
              </button>

              <span className="qty-number">{quantity}</span>

              <button
                className="qty-btn"
                onClick={() => addToCart(item)}
              >
                +
              </button>
            </div>
          )}
        </>
      )}

      {outOfStock && (
        <button className="add-btn" disabled>
          Unavailable
        </button>
      )}
    </div>
  );
}
